import {trainingRehearsalChecks,trainingRehearsalChecksView} from './expedition-training-rehearsal-checks.mjs';
import {SKILLS,DEFENSES,TYPES,ATTR,EXPEDITIONS} from './expedition-data.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function trainingRehearsalView(p,{stale=false}={}){
 if(!p)return '';
 let checks=null;try{checks=trainingRehearsalChecks(p);}catch{}
 const a=p.summary.before,b=p.summary.after,rows=[['远征结果',a.won?'通关':'止步',b.won?'通关':'止步'],['已通关场数',a.cleared,b.cleared],['生还角色',a.alive,b.alive],['总回合',a.rounds,b.rounds],['本人施放次数',a.personal.casts,b.personal.casts],['本人施放法力',a.personal.castMana,b.personal.castMana],['本人实际伤害',a.personal.damage,b.personal.damage],['本人实际治疗',a.personal.healing,b.personal.healing],['本人增益施加',a.personal.buffApplications,b.personal.buffApplications],['本人阻止救护次数',a.personal.healingBlocks,b.personal.healingBlocks]];
 for(const r of p.resources||[])rows.unshift([r.key==='maxHp'?'本人出发生命上限':'本人出发法力上限',r.before,r.after]);
 for(const [key,name] of Object.entries({herb:'药草',rune:'符纸',arrow:'箭矢'}))rows.push(['本人消耗'+name,a.personal.supplies[key],b.personal.supplies[key]]);
 const route=p.reports?.before?.config?.expedition,source=EXPEDITIONS[route]?.name||'试演时路线';
 return `<section class="training-rehearsal" data-training-stale="${stale}"><h3 id="training-rehearsal-heading" tabindex="-1">${esc(p.name)} · 培养草案试演${stale?' · 已过期':''}</h3>${stale?'<p class="ready-diff" role="status">公会、准备或培养草案已变化。下方保留的是早前试演，不代表现在的准备；请重新核对准备及草案，再试演。</p>':''}<p>${esc(source)} · 种子${p.seed} · ${stale?'试演时':'当前'}公会资产与草案使用同一出征方案分别完整模拟；没有出征、支付经验或发放奖励。只改本人的永久训练，课程、后期进阶、装备与指令保留。</p><p>草案退回 ${p.quote.refund} 经验、花费 ${p.quote.cost} 经验；可用经验 ${p.quote.availableBefore} → ${p.quote.availableAfter}。只有明确应用草案才会支付或退回。</p><p>${[...(p.attributes||[]).map(r=>`${ATTR[r.key]}出发总值 ${r.before}→${r.after}`),...p.skills.map(r=>`${SKILLS[r.skill].name}静态等级 ${r.before}→${r.after}`),...p.defenses.map(r=>`${TYPES[r.type]} / ${DEFENSES[r.defense].name}出发等级 ${r.before}→${r.after}`)].map(esc).join('；')||'未列出属性或技能等级变化；检定均值与被动来源仍须核对'}</p>${trainingRehearsalChecksView(checks)}<div class="training-rehearsal-scroll"><table><thead><tr><th>实测项</th><th>${stale?'早前当前培养':'当前培养'}</th><th>${stale?'早前培养草案':'培养草案'}</th></tr></thead><tbody>${rows.map(([name,x,y])=>`<tr><th>${name}</th><td>${x}</td><td>${y}</td></tr>`).join('')}</tbody></table></div><p>这是一个种子的功能比较，不是胜率或稳定收益；不同动作可能改变后续随机抽取顺序。止步后的较少回合不能当作效率优势，伤害差异也不等于该技能的独立贡献。</p><button data-training-report="before" ${stale?'disabled':''}>查看当前培养战报</button><button data-training-report="after" ${stale?'disabled':''}>查看草案战报</button><button data-training-plan-return>返回草案核对费用与目标</button></section>`;
}
